import { Button } from '@mui/material';
import { Link } from 'react-router-dom';
import { TOKENS } from '../../tokens';

const premiumSx = (variant) => ({
  position: 'relative',
  overflow: 'hidden',
  fontWeight: 600,
  letterSpacing: '0.02em',
  isolation: 'isolate',
  borderRadius: TOKENS.radius.sm,
  transition: TOKENS.transition,
  '& > span, & > .MuiButton-startIcon, & > .MuiButton-endIcon': {
    position: 'relative',
    zIndex: 1,
  },
  ...(variant === 'contained' && {
    background: TOKENS.colors.lime,
    color: '#000000',
    border: `1px solid ${TOKENS.colors.lime}`,
    boxShadow: `0 8px 28px ${TOKENS.glow.lime}`,
    '&:hover': {
      transform: 'translateY(-3px)',
      background: TOKENS.colors.limeBright,
      borderColor: TOKENS.colors.limeBright,
      boxShadow: `0 14px 36px rgba(76, 198, 110, 0.32)`,
    },
    '&:active': { transform: 'translateY(-1px)' },
  }),
  ...(variant === 'purple' && {
    background: TOKENS.colors.purple,
    color: '#FFFFFF',
    border: `1px solid ${TOKENS.colors.violet}`,
    boxShadow: `0 8px 28px ${TOKENS.glow.purple}`,
    '&:hover': {
      transform: 'translateY(-3px)',
      background: TOKENS.colors.violet,
      boxShadow: `0 14px 36px rgba(159, 110, 218, 0.32)`,
    },
    '&:active': { transform: 'translateY(-1px)' },
  }),
  ...(variant === 'outlined' && {
    borderWidth: '1px',
    borderColor: TOKENS.colors.violet,
    color: TOKENS.colors.textPrimary,
    background: 'transparent',
    '&:hover': {
      transform: 'translateY(-3px)',
      borderColor: TOKENS.colors.purpleSoft,
      background: 'rgba(159, 110, 218, 0.08)',
      boxShadow: `0 10px 32px ${TOKENS.glow.violet}`,
    },
    '&:active': { transform: 'translateY(-1px)' },
  }),
  ...(variant === 'ghost' && {
    color: TOKENS.colors.textSecondary,
    background: 'transparent',
    '&:hover': {
      color: TOKENS.colors.violet,
      background: 'rgba(159, 110, 218, 0.06)',
    },
  }),
});

const GlowButton = ({
  children,
  to,
  href,
  onClick,
  variant = 'contained',
  size = 'large',
  fullWidth = false,
  disabled = false,
  startIcon,
  endIcon,
  sx = {},
  ...rest
}) => {
  const combinedSx = { ...premiumSx(variant), ...sx };
  const muiVariant = variant === 'ghost' ? 'text' : 'contained';

  const shared = {
    variant: muiVariant,
    size,
    fullWidth,
    disabled,
    startIcon,
    endIcon,
    sx: combinedSx,
    ...rest,
  };

  if (to) {
    return (
      <Button component={Link} to={to} {...shared}>
        {children}
      </Button>
    );
  }

  if (href) {
    return (
      <Button component="a" href={href} target="_blank" rel="noopener noreferrer" {...shared}>
        {children}
      </Button>
    );
  }

  return (
    <Button onClick={onClick} {...shared}>
      {children}
    </Button>
  );
};

export default GlowButton;
